import {spawn} from 'node:child_process';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {once} from 'node:events';
import {randomUUID} from 'node:crypto';
import path from 'node:path';
export const dataDir=path.resolve(process.env.CREW_DATA_DIR??'./data');
export async function persist(name,value){await mkdir(dataDir,{recursive:true,mode:0o700});await writeFile(path.join(dataDir,name),JSON.stringify(value,null,2)+'\n',{mode:0o600});}
export async function load(name,fallback={}){try{return JSON.parse(await readFile(path.join(dataDir,name),'utf8'));}catch(error){if(error.code==='ENOENT')return fallback;throw error;}}
export async function child(command,args,options={}) {
  const processChild=spawn(command,args,{...options,stdio:['ignore','pipe','pipe']});
  let stdout='',stderr='';
  processChild.stdout.on('data',chunk=>{stdout+=chunk;});
  processChild.stderr.on('data',chunk=>{stderr+=chunk;});
  const timer=setTimeout(()=>processChild.kill('SIGKILL'),options.deadline??20000);
  try{const [code,signal]=await once(processChild,'exit');if(code!==0)throw new Error(`${command} exited ${code??signal}: ${stderr}`);return{stdout,stderr,code};}
  finally{clearTimeout(timer);if(processChild.exitCode===null&&processChild.signalCode===null)processChild.kill('SIGKILL');}
}
export async function startServer() {
  await mkdir(dataDir,{recursive:true,mode:0o700});
  const server=spawn(process.execPath,['packages/server/src/index.js'],{env:{...process.env,PORT:'0',CREW_DATA_DIR:dataDir,CREW_SECRET:'crew-acceptance-fixed-secret'},stdio:['ignore','pipe','pipe']});
  let stdout='',stderr='';let readyResolve,readyReject;
  const ready=new Promise((resolve,reject)=>{readyResolve=resolve;readyReject=reject;});
  const timer=setTimeout(()=>readyReject(new Error('Server readiness deadline exceeded: '+stderr)),8000);
  server.stdout.on('data',chunk=>{stdout+=chunk;for(const line of stdout.split('\n')){try{const record=JSON.parse(line);if(record.ready)readyResolve(record);}catch{}}});
  server.stderr.on('data',chunk=>{stderr+=chunk;});
  server.on('error',readyReject);
  server.on('exit',(code,signal)=>readyReject(new Error(`Server exited before readiness: ${code??signal} ${stderr}`)));
  await persist('owned-processes.json',[{pid:server.pid,kind:'server',startedAt:new Date().toISOString()}]);
  async function stop(){
    if(server.exitCode===null&&server.signalCode===null){server.kill('SIGTERM');const deadline=setTimeout(()=>server.kill('SIGKILL'),3500);try{await once(server,'exit');}finally{clearTimeout(deadline);}}
    await persist('owned-processes.json',[]);
    if(server.exitCode!==0)throw new Error('Server did not stop cleanly: '+(server.exitCode??server.signalCode));
  }
  try{const record=await ready;return{url:`http://127.0.0.1:${record.port}`,stop,logs:()=>({stdout,stderr})};}
  catch(error){await stop();throw error;}
  finally{clearTimeout(timer);}
}
export function createContext(url,ids,checks,{readOnly=false}={}) {
  const clients=ids.clients??{};
  const artifactPrefix=randomUUID(),artifacts={};
  function artifactPath(name){
    if(typeof name!=='string'||!name||path.basename(name)!==name)throw new Error('Acceptance artifact label must be a filename');
    return artifacts[name]??=path.join(dataDir,artifactPrefix+'-'+name);
  }
  async function check(name,fn){try{const result=await fn();if(result===false)throw new Error('Assertion returned false');checks.push({name,ok:true});return result;}catch(error){checks.push({name,ok:false,error:error.message});throw error;}}
  async function request(method,route,body,{actor='owner',raw=false,binary=false,headers:extra={}}={}) {
    const client=clients[actor]??{};
    const headers={'X-Crew-Request':'1',...extra};
    if(client.token)headers.authorization='Bearer '+client.token;else if(client.cookie)headers.cookie=client.cookie;
    if(body!==undefined&&!raw)headers['content-type']='application/json';
    const response=await fetch(url+'/api/v1'+route,{method,headers,body:body===undefined?undefined:raw?body:JSON.stringify(body),signal:AbortSignal.timeout(10000)});
    const cookie=response.headers.get('set-cookie');if(cookie)clients[actor]={...client,cookie:cookie.split(';')[0]};
    const data=binary?Buffer.from(await response.arrayBuffer()):(response.headers.get('content-type')??'').includes('json')?await response.json():await response.text();
    return {status:response.status,data,headers:response.headers};
  }
  async function api(method,route,body,actor='owner') {const result=await request(method,route,body,{actor});if(result.status<200||result.status>=300)throw new Error(`${method} ${route} ${result.status}: ${JSON.stringify(result.data)}`);return result.data;}
  async function signup(actor,{name,email,password}){clients[actor]={email,password};const result=await api('POST','/auth/signup',{name,email,password},actor);clients[actor].user=result.user;return result.user;}
  async function cli(args,actor='owner') {
    const config=path.join(dataDir,`cli-${actor}.json`);
    const client=clients[actor];
    if(readOnly)await readFile(config,'utf8');
    else await writeFile(config,JSON.stringify({url,...(client?.token?{token:client.token}:{cookie:client?.cookie})}),{mode:0o600});
    const result=await child('node_modules/.bin/crew',[...args,'--url',url,'--config',config,'--json'],{env:process.env,deadline:12000});
    return JSON.parse(result.stdout);
  }
  ids.clients=clients;
  return {url,ids,clients,request,api,check,signup,cli,dataDir,artifactPath,artifactFiles:()=>({...artifacts})};
}

import assert from 'node:assert/strict';
import {readdir,readFile,lstat,access} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import path from 'node:path';
import {existsSync} from 'node:fs';
import {maintainedCensus} from './audit-files.mjs';
import {dataDir,persist,load,startServer,createContext,child} from './acceptance-runtime.mjs';
const mode=process.argv[2];
const checks=[];
let server;
let context;
let error;
try{
  if(['smoke','restart','browser','remount'].includes(mode)){
    const ids=await load('acceptance-state.json');
    server=await startServer();
    const ctx=createContext(server.url,ids,checks,{readOnly:mode!=='smoke'});
    context=ctx;
    if(mode==='smoke'){
      const email=`acceptance-${Date.now()}@crew.test`;
      await ctx.check('signup/login and httpOnly session',async()=>{const user=await ctx.signup('owner',{name:'Acceptance Owner',email,password:'acceptance long password'});assert.equal(user.email,email);const me=await ctx.api('GET','/me');assert.equal(me.user.id,user.id);});
      for(const lane of ['people','work','insight']){
        const module=await import(new URL(`./checks/${lane}.mjs`,import.meta.url));
        await module.smoke(ctx);
      }
      await persist('acceptance-state.json',ids);
    }else if(mode==='restart'){
      assert.ok(ids.clients?.owner,'Existing smoke state is required');
      for(const lane of ['people','work','insight'])await(await import(new URL(`./checks/${lane}.mjs`,import.meta.url))).restart(ctx);
    }else if(mode==='browser'){
      await ctx.check('Chromium login, board drag, search and inbox',async()=>{
        const result=await child('/usr/bin/python3',['scripts/browser-smoke.py'],{env:{...process.env,CREW_BROWSER_URL:server.url,CREW_ACCEPTANCE_STATE:path.join(dataDir,'acceptance-state.json')},deadline:75000});
        const report=JSON.parse(result.stdout.trim().split('\n').at(-1));assert.equal(report.ok,true);
        checks.push(...report.checks);
      });
    }else{
      await ctx.check('CLI executable mode and whoami after fresh mount',async()=>{const stat=await lstat('packages/cli/bin/crew.js');assert.ok(stat.mode&0o111);const result=await ctx.cli(['whoami']);assert.equal(result.user.id,ids.clients.owner.user.id);});
      const module=await import(new URL('./checks/work.mjs',import.meta.url));await module.remount(ctx);
    }
  }else if(mode==='audit'){
    const census=await maintainedCensus();
    checks.push({name:'Complete maintained-file identity census',ok:true,...census});
    const {countProject,isProductionPath}=await import('./count-loc.mjs');
    const source=await readFile('scripts/count-loc.mjs');
    assert.equal(createHash('sha256').update(source).digest('hex'),'f73b6acb7d073e90631936ad62be8705a9c2a2f93c7e2097e7ca4f5c062f12ab');
    checks.push({name:'Frozen counter hash',ok:true});
    const count=await countProject(process.cwd());assert.ok(count.total>=10000,'At least 10000 production LOC');
    const largest=[];
    for(const file of count.files){const content=await readFile(file.path,'utf8');const lines=content.split('\n').length-(content.endsWith('\n')?1:0);assert.ok(lines<=999,`${file.path}: ${lines} physical lines`);largest.push({...file,physicalLines:lines});}
    checks.push({name:'Production census, scope and file-size ceiling',ok:true,total:count.total,packages:count.packages,largest:largest.sort((a,b)=>b.prod-a.prod).slice(0,15)});
    for(const name of ['README.md','docs/api.md','docs/architecture.md','docs/api-people.md','docs/api-work.md','docs/api-insight.md'])await access(name);
    checks.push({name:'Required operational and lane documentation',ok:true});
    for(const lane of ['people','work','insight'])await(await import(new URL(`./checks/${lane}.mjs`,import.meta.url))).audit({checks});
    const meta=JSON.parse(await readFile('packages/web/dist/meta.json','utf8'));
    assert.ok(!Object.keys(meta.inputs).some(name=>/devtools|test-utils|preact\/debug|\/test\//.test(name)));
    assert.ok(Object.values(meta.outputs).every(output=>!(output.imports??[]).some(item=>item.external)),'Browser bundle contains unresolved external imports');
    checks.push({name:'Production browser bundle',ok:true});
  }else if(mode==='closed'){
    for(const entry of await load('owned-processes.json',[])){let live=false;try{process.kill(entry.pid,0);live=true;}catch{}assert.equal(live,false,`Owned ${entry.kind} ${entry.pid} remains`);}
    const live=[];
    for(const name of await readdir('/proc')){
      if(!/^\d+$/.test(name))continue;
      let command;
      try{command=await readFile('/proc/'+name+'/cmdline','utf8');}
      catch(error){if(error.code==='ENOENT'||error.code==='ESRCH')continue;throw error;}
      if(/chromium|chromedriver|chrome_crashpad|scripts\/browser-smoke\.py|packages\/server\/src\/index\.js/.test(command))live.push({pid:Number(name),kind:command.includes('packages/server/src/index.js')?'server':'browser'});
    }
    assert.equal(live.length,0,'Owned application processes remain: '+JSON.stringify(live));
    checks.push({name:'No retained or live application/browser processes in selected Sandbox',ok:true});
  }else throw new Error('Expected smoke, restart, browser, remount, audit or closed');
}catch(cause){error=cause;checks.push({name:'Mode completion',ok:false,error:cause.message});}
finally{if(server){try{await server.stop();}catch(cause){error??=cause;checks.push({name:'Server clean shutdown',ok:false,error:cause.message});}const logs=server.logs();if(error)console.error(JSON.stringify({serverLogs:logs}));}}
const result={mode,artifactFiles:context?.artifactFiles()??{},checks,pass:checks.filter(c=>c.ok).length,fail:checks.filter(c=>!c.ok).length,ok:!error};
console.log(JSON.stringify(result));
if(error)process.exitCode=1;

import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
export async function smoke(ctx) {
  const {ids,api,check}=ctx;
  await check('dashboard counts throughput and burndown reuse visible canonical work',async()=>{
    const issues=await api('GET','/projects/'+ids.projectId+'/issues?limit=200');
    const report=await api('GET','/dashboard?orgId='+ids.orgId+'&projectId='+ids.projectId+'&sprintId='+ids.sprintId);
    assert.equal(report.totals.issues,issues.items.length);assert.ok(report.throughput.some(week=>week.issues>0));
    assert.deepEqual(report.burndown,await api('GET','/sprints/'+ids.sprintId+'/burndown'));
    assert.equal((await ctx.request('GET','/dashboard?orgId='+ids.orgId+'&projectId='+ids.privateProjectId,undefined,{actor:'guest'})).status,403);
  });
  await check('JSON CSV export validated preview and atomic remapped import preserve required content',async()=>{
    const document=await api('GET','/projects/'+ids.projectId+'/export');
    assert.equal(document.format,'crew.project');
    const csv=await ctx.request('GET','/projects/'+ids.projectId+'/export?format=csv');assert.equal(csv.status,200);assert.match(csv.data,/"number","title"/);assert.ok(csv.data.includes('Acceptance issue release'));
    const preview=await api('POST','/orgs/'+ids.orgId+'/import',{document,key:'ROUNDTRIP',preview:true});assert.equal(preview.preview.counts.issues,document.issues.length);
    const imported=await api('POST','/orgs/'+ids.orgId+'/import',{document,key:'ROUNDTRIP',name:'Acceptance imported project'});
    ids.importedProjectId=imported.project.id;ids.importedMappings=imported.mappings;ids.importedCounts=imported.counts;
    const again=await api('GET','/projects/'+imported.project.id+'/export');
    for(const key of ['issues','comments','labels','relations'])assert.equal(again[key].length,document[key].length,key);
    for(const source of document.issues){const item=again.issues.find(issue=>issue.id===imported.mappings.issues[source.id]);assert.ok(item);for(const key of ['title','description','priority','estimate','dueDate','createdAt','updatedAt'])assert.equal(item[key],source[key]);assert.equal(item.parentId,source.parentId?imported.mappings.issues[source.parentId]:null);}
    const invalid=structuredClone(document);invalid.issues[0].statusId='invalid-status';
    const bad=await ctx.request('POST','/orgs/'+ids.orgId+'/import',{document:invalid,key:'INVALID'});assert.equal(bad.status,422);
    assert.equal((await ctx.request('POST','/orgs/'+ids.orgId+'/import',{document,key:'DENIED'}, {actor:'guest'})).status,403);
  });
  await check('actual dashboard and streamed project export import CLI families roundtrip',async()=>{
    const file=ctx.artifactPath('insight-project.json');
    const exported=await ctx.cli(['export',ids.projectId,'--output',file]);assert.ok(exported.bytes>0);assert.equal(exported.sha256.length,64);
    const bytes=await readFile(file),document=JSON.parse(bytes.toString('utf8'));assert.ok(document.issues.some(issue=>issue.id===ids.issueId));
    await assert.rejects(()=>ctx.cli(['export',ids.projectId,'--output',file]),/EEXIST/);assert.deepEqual(await readFile(file),bytes);
    const preview=await ctx.cli(['import','--org',ids.orgId,'--file',file,'--key','CLICOPY','--preview']);assert.equal(preview.preview.counts.issues,document.issues.length);
    const imported=await ctx.cli(['import','--org',ids.orgId,'--file',file,'--key','CLICOPY','--yes']);ids.cliImportedProjectId=imported.project.id;
    assert.equal(imported.counts.relations,document.relations.length);
    const report=await ctx.cli(['dashboard','--org',ids.orgId,'--project',ids.projectId]);assert.equal(report.totals.issues,document.issues.length);
  });
}
export async function restart(ctx) {
  await ctx.check('imported project closure and reporting persist across a new server process',async()=>{
    const document=await ctx.api('GET','/projects/'+ctx.ids.importedProjectId+'/export');
    for(const key of ['issues','comments','labels','relations'])assert.equal(document[key].length,ctx.ids.importedCounts[key]);
    const issue=document.issues.find(item=>item.id===ctx.ids.importedMappings.issues[ctx.ids.issueId]);assert.equal(issue.title,ctx.ids.issueExpected.title);
    const project=(await ctx.api('GET','/projects/'+ctx.ids.cliImportedProjectId)).project;assert.equal(project.key,'CLICOPY');
    assert.equal((await ctx.api('GET','/dashboard?orgId='+ctx.ids.orgId+'&projectId='+ctx.ids.importedProjectId)).totals.issues,document.issues.length);
  });
}
export async function remount(ctx) {
  await ctx.check('saved dashboard CLI reads imported persisted project after fresh mount',async()=>{
    const report=await ctx.cli(['dashboard','--org',ctx.ids.orgId,'--project',ctx.ids.importedProjectId]);assert.equal(report.totals.issues,ctx.ids.importedCounts.issues);
  });
}
export async function audit({checks}) {
  const docs=await readFile('docs/api-insight.md','utf8');for(const term of ['export:read','import:write','externalIssueMap','getBurndown','atomic','CSV','SVG','next_issue_number'])assert.ok(docs.includes(term),term);
  checks.push({name:'Dashboard canonical ledger and streamed validated remapped project transfer contracts documented; HTTP rollback/roundtrip and actual CLI suites qualify behavior',ok:true});
}

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { writeFile, readFile } from 'node:fs/promises';
const attachmentBytes = Buffer.from([0, 255, 13, 10, 65, 90, 0, 128, 42]);
export async function createProject(ctx) {
  await ctx.check('project create workflow update and permission-filtered list', async () => {
    const { project } = await ctx.api('POST', '/orgs/' + ctx.ids.orgId + '/projects', {
      key: 'ACC', name: 'Acceptance project', description: 'Acceptance planning workspace'
    });
    ctx.ids.projectId = project.id; ctx.ids.projectKey = project.key;
    const statuses = project.statuses.map(({ id, name, category }) => ({ id, name: category === 'active' ? 'Building' : name, category }));
    const updated = await ctx.api('PUT', '/projects/' + project.id + '/workflow', { statuses });
    assert.deepEqual(updated.statuses.map(status => status.id), project.statuses.map(status => status.id));
    ctx.ids.browserTargetStatusId = updated.statuses.find(status => status.category === 'active').id;
    assert((await ctx.api('GET', '/projects?orgId=' + ctx.ids.orgId)).items.some(item => item.id === project.id));
    assert.equal((await ctx.request('PATCH', '/projects/' + project.id, { name: 'Denied' }, { actor: 'member' })).status, 403);
  });
}
export async function smoke(ctx) {
  const { api, check, ids } = ctx;
  const { project } = await api('GET', '/projects/' + ids.projectId);
  await check('board move within and across columns and atomic bulk fields', async () => {
    const first = (await api('POST', '/projects/' + project.id + '/issues', { title: 'Planning first', estimate: 3 })).issue;
    const second = (await api('POST', '/projects/' + project.id + '/issues', { title: 'Planning second', estimate: 8 })).issue;
    ids.planningIssueId = first.id; ids.planningCarryIssueId = second.id;
    await api('POST', '/issues/' + second.id + '/move', { statusId: project.statuses[0].id, beforeId: first.id });
    const board = await api('GET', '/projects/' + project.id + '/board');
    const ordered = board.columns[0].issues.map(issue => issue.id);
    assert(ordered.indexOf(second.id) < ordered.indexOf(first.id));
    const edited = await api('POST', '/projects/' + project.id + '/issues/bulk', {
      issueIds: [first.id, second.id], changes: { statusId: project.statuses[1].id, assigneeId: ctx.clients.member.user.id, labelIds: [ids.issueLabelId] }
    });
    assert.equal(edited.count, 2); assert(edited.items.every(issue => issue.statusId === project.statuses[1].id && issue.labels[0].id === ids.issueLabelId));
    const denied = await ctx.request('POST', '/projects/' + project.id + '/issues/bulk', { issueIds: [first.id, second.id], changes: { statusId: project.statuses[2].id, labelIds: ['invalid-label'] } });
    assert.equal(denied.status, 422); assert.equal((await api('GET', '/issues/' + first.id)).issue.statusId, project.statuses[1].id);
  });
  await check('sprint lifecycle scope history carry-over and daily burndown persist', async () => {
    const today = new Date().toISOString().slice(0, 10);
    const nextWeek = new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 10);
    const end = new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10);
    const sprint = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Acceptance sprint', goal: 'Prove delivery', startDate: today, endDate: nextWeek })).sprint;
    const carry = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Acceptance carry-over', startDate: nextWeek, endDate: end })).sprint;
    ids.sprintId = sprint.id; ids.carrySprintId = carry.id;
    await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [ids.planningIssueId, ids.planningCarryIssueId] });
    await api('DELETE', '/sprints/' + sprint.id + '/issues/' + ids.planningCarryIssueId);
    await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [ids.planningCarryIssueId] });
    await api('POST', '/sprints/' + sprint.id + '/start', {});
    await api('PATCH', '/issues/' + ids.planningIssueId, { statusId: project.statuses[2].id });
    const result = await api('POST', '/sprints/' + sprint.id + '/complete', { carryOverSprintId: carry.id });
    assert.deepEqual(result.result.completedIssueIds, [ids.planningIssueId]);
    assert.deepEqual(result.result.carriedIssueIds, [ids.planningCarryIssueId]);
    const burndown = await api('GET', '/sprints/' + sprint.id + '/burndown');
    assert.equal(burndown.days[0].scope, 11); assert.equal(burndown.days[0].remaining, 8);
    ids.planningBoardOrder = (await api('GET', '/projects/' + project.id + '/board')).columns.map(column => ({ statusId: column.status.id, issueIds: column.issues.filter(issue => [ids.planningIssueId, ids.planningCarryIssueId].includes(issue.id)).map(issue => issue.id) }));
  });
  await check('attachment raw upload SHA-256 metadata exact bytes and error cleanup', async () => {
    const sha256 = createHash('sha256').update(attachmentBytes).digest('hex');
    const uploaded = await ctx.request('POST', '/issues/' + ids.planningIssueId + '/attachments?name=acceptance.bin', attachmentBytes, { raw: true, headers: { 'Content-Type': 'application/octet-stream', 'X-Content-SHA256': sha256 } });
    assert.equal(uploaded.status, 201); const attachment = uploaded.data.attachment;
    ids.attachmentId = attachment.id; ids.attachmentSha256 = sha256;
    assert.equal(attachment.size, attachmentBytes.length); assert.equal(attachment.sha256, sha256);
    const downloaded = await ctx.request('GET', '/attachments/' + attachment.id + '/download', undefined, { binary: true });
    assert.equal(downloaded.status, 200); assert.deepEqual(downloaded.data, attachmentBytes);
    const invalid = await ctx.request('POST', '/issues/' + ids.planningIssueId + '/attachments?name=bad.bin', attachmentBytes, { raw: true, headers: { 'Content-Type': 'application/octet-stream', 'X-Content-SHA256': '0'.repeat(64) } });
    assert.equal(invalid.status, 422); assert.equal((await api('GET', '/issues/' + ids.planningIssueId + '/attachments')).items.length, 1);
  });
  await check('work guest public HTTP denial outside its granted project', async () => {
    await api('POST', '/projects/' + project.id + '/guests', { userId: ctx.clients.guest.user.id });
    const hidden = (await api('POST', '/orgs/' + ids.orgId + '/projects', { key: 'PRIVATE', name: 'Private planning' })).project;
    ids.privateProjectId = hidden.id;
    assert.equal((await ctx.request('GET', '/projects/' + hidden.id + '/board', undefined, { actor: 'guest' })).status, 403);
    const projects = await api('GET', '/orgs/' + ids.orgId + '/projects', undefined, 'guest');
    assert.deepEqual(projects.items.map(item => item.id), [project.id]);
    assert.equal((await ctx.request('POST', '/issues/' + ids.planningIssueId + '/move', { statusId: project.statuses[0].id }, { actor: 'guest' })).status, 403);
  });
  await check('actual project board sprint and streaming attachment CLI commands', async () => {
    assert.equal((await ctx.cli(['project', 'show', ids.projectId])).project.key, ids.projectKey);
    assert((await ctx.cli(['board', 'show', ids.projectId])).columns.length >= 3);
    assert.equal((await ctx.cli(['sprint', 'show', ids.sprintId])).sprint.status, 'completed');
    const source = ctx.artifactPath('cli-attachment-source.bin'), output = ctx.artifactPath('cli-attachment-output.bin');
    await writeFile(source, attachmentBytes, { mode: 0o600, flag: 'wx' });
    const attachment = (await ctx.cli(['board', 'attach', ids.planningCarryIssueId, '--file', source])).attachment;
    ids.cliAttachmentId = attachment.id;
    const downloaded = await ctx.cli(['board', 'download', attachment.id, '--output', output]);
    assert.equal(downloaded.sha256, ids.attachmentSha256); assert.deepEqual(await readFile(output), attachmentBytes);
    await assert.rejects(() => ctx.cli(['board', 'download', attachment.id, '--output', output]), /EEXIST/);
    assert.deepEqual(await readFile(output), attachmentBytes);
  });
}
export async function restart(ctx) {
  const { api, ids } = ctx;
  await ctx.check('project workflow board sprint and exact attachment survive restart', async () => {
    const project = (await api('GET', '/projects/' + ids.projectId)).project;
